func writeCachedArbiterJSON(w http.ResponseWriter, synthesis, modelName string) error {
	resp := map[string]interface{}{
		"object": "chat.completion",
		"model":  modelName,
		"choices": []map[string]interface{}{
			{
				"index": 0,
				"message": map[string]string{
