	if err != nil {
		return fmt.Errorf("fusion: marshal cached arbiter JSON: %w", err)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, werr := w.Write(b)
	return werr
}

