func (f *fakeTransport) on(url string, h http.HandlerFunc) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.handlers[url] = h
	if _, ok := f.counters[url]; !ok {
		var v int32
		f.counters[url] = &v
	}
